SEED_NOTICES = [{'id': 1, 'title': 'Overhead Water Tank Deep Cleaning & Disinfection Schedule', 'content': 'Dear Residents,\n\nPlease be informed that annual chemical cleaning and pressure-washing of both Block A and Block B overhead and underground water reservoirs is scheduled for Sunday, August 30, from 8:00 AM to 3:00 PM.\n\n• Water supply will be temporarily interrupted during these hours.\n• Please store sufficient water in advance for morning household requirements.\n• Normal water supply will resume by 4:00 PM post-disinfection.\n\nFor any urgent queries, contact Caretaker Sanjoy Chakraborty (+91 98300 12345).', 'category': 'WATER_SUPPLY', 'priority': 'URGENT', 'is_pinned': 1, 'posted_by': 'Somenath Halder', 'posted_by_role': 'Secretary', 'status': 'ACTIVE', 'created_at': '2026-08-22 12:42:43', 'updated_at': '2026-08-22 12:42:43'}, {'id': 2, 'title': 'Notification: 18th Annual General Meeting (AGM 2026)', 'content': "Notice is hereby given that the 18th Annual General Meeting (AGM) of South Dumdum Enclave Residents' Association will be held on Sunday, September 14, at 6:30 PM at the Community Hall (Ground Floor).\n\nAgenda Items:\n1. Review & passing of FY 2025-26 Audited Accounts and Balance Sheet.\n2. Review of Reserve Sinking Fund and Building Repainting Plan.\n3. Proposal for Common Area Rooftop Solar Panel Installation.\n4. Election / Confirmation of Executive Committee for 2026-2028.\n\nAll flat owners are cordially requested to attend punctually.", 'category': 'AGM_MEETING', 'priority': 'HIGH', 'is_pinned': 1, 'posted_by': 'Dr. Asit Kumar Bera', 'posted_by_role': 'President', 'status': 'ACTIVE', 'created_at': '2026-08-22 12:42:43', 'updated_at': '2026-08-22 12:42:43'}, {'id': 3, 'title': 'Schindler Lift AMC Bi-Monthly Lubrication & Safety Check', 'content': 'The routine bi-monthly comprehensive safety check and brake pad inspection by Schindler India engineers will be carried out this Thursday between 11:00 AM and 2:00 PM.\n\nEach lift will be paused individually for approximately 45 minutes to minimize resident inconvenience. Power backup generator will be on standby.', 'category': 'MAINTENANCE', 'priority': 'NORMAL', 'is_pinned': 0, 'posted_by': 'Swapnadeep Ganguly', 'posted_by_role': 'Treasurer', 'status': 'ACTIVE', 'created_at': '2026-08-22 12:42:43', 'updated_at': '2026-08-22 12:42:43'}, {'id': 4, 'title': 'Sharodotsav / Durga Puja 2026 Cultural Sub-Committee Formation', 'content': "With the festive season approaching, all interested residents and youth members are invited to join the SDERA Cultural Sub-Committee for organizing this year's Durga Puja, Bhog distribution, and evening cultural performances.\n\nPreliminary planning meetup: This Saturday at 7:00 PM in the Society Lounge. Your creative ideas and volunteer participation are warmly welcomed!", 'category': 'EVENTS_FESTIVAL', 'priority': 'NORMAL', 'is_pinned': 0, 'posted_by': 'Somenath Halder', 'posted_by_role': 'Secretary', 'status': 'ACTIVE', 'created_at': '2026-08-22 12:42:43', 'updated_at': '2026-08-22 12:42:43'}, {'id': 5, 'title': 'Updated Security Protocols & Caretaker Intercom Extensions', 'content': 'To bolster perimeter safety and smooth visitor entry:\n\n• Night Delivery Protocol: All food (Swiggy/Zomato) and courier deliveries after 10:00 PM will require prior gate clearance via intercom.\n• Intercom Speed Dial: Guard Cabin (#100), Caretaker Office (#101).\n• Caretaker Mobile: +91 98300 12345.\n\nVisitors without resident verification will be requested to register their contact numbers at the main security desk.', 'category': 'SECURITY', 'priority': 'NORMAL', 'is_pinned': 0, 'posted_by': 'Sanjoy Chakraborty', 'posted_by_role': 'Caretaker', 'status': 'ACTIVE', 'created_at': '2026-08-22 12:42:43', 'updated_at': '2026-08-22 12:42:43'}]
